script:
(function () {
  'use strict';
  // Down payment, cash to close and loan amount, solved three ways.
  //   Closing costs C are a % of the price (C = c * P) or a flat dollar amount.
  //   Cash -> price:   P = cash / (d + c) with % closing costs, P = (cash - C) / d with $ costs
  //                    (P = cash / d when closing costs are not paid from the cash).
  //   Price -> cash:   cash = d * P + C.
  //   Both -> down %:  down = cash - C; d = down / P.
  //   P&I: M = L * i / (1 - (1 + i)^-n), i = rate / 12, n = years * 12 (M = L / n at 0%).
  // Verified in Node (scratchpad tests/w3re): $100,000 cash, 20% down, 3% closing costs -> $434,782.61
  //   price, $86,956.52 down, $13,043.48 costs, $347,826.09 loan; $500,000 at 20% + 3% -> $115,000
  //   cash; $500,000 price with $100,000 cash -> 17.0% down, $415,000 loan (all three match a
  //   published calculator's defaults); P&I on $347,826.09 at 7.373% for 30 yrs = $2,401.87 (closed
  //   form, matches the same calculator's rounded $2,402); 0% rate -> L / n; $ closing costs; no
  //   NaN/Infinity on blank, zero or negative input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var OPTIONS = [
    { pct: 0, note: 'VA or USDA loans only' },
    { pct: 3, note: 'Lowest conventional programs' },
    { pct: 3.5, note: 'FHA minimum (580+ credit score)' },
    { pct: 5, note: 'Conventional with PMI' },
    { pct: 10, note: 'Conventional with PMI' },
    { pct: 15, note: 'Conventional with PMI' },
    { pct: 20, note: 'Conventional, no PMI' },
    { pct: 25, note: 'Conventional, no PMI' }
  ];
  var LABELS = { cash: 'Home price you can afford', price: 'Cash needed at closing', both: 'Your down payment' };

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(loan, annualPct, months) {
    if (loan <= 0 || months <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return loan / months;
    return loan * i / (1 - Math.pow(1 + i, -months));
  }

  function closingFor(price, o) {
    if (!o.include) return 0;
    return o.ccUnit === 'percent' ? price * o.cc / 100 : o.cc;
  }

  // Returns { price, down, closing } or { error }.
  function solve(mode, o) {
    var price, down, closing;
    if (mode === 'cash') {
      var d = o.pct / 100;
      if (d === 0) return { error: 'Enter a down payment percentage above 0% to work out a price from your cash.' };
      if (o.include && o.ccUnit === 'percent') {
        price = o.cash / (d + o.cc / 100);
      } else {
        var spare = o.cash - (o.include ? o.cc : 0);
        if (spare <= 0) return { error: 'Your cash needs to be more than the closing costs.' };
        price = spare / d;
      }
      down = price * d;
      closing = closingFor(price, o);
    } else if (mode === 'price') {
      price = o.price;
      down = price * o.pct / 100;
      closing = closingFor(price, o);
    } else {
      price = o.price;
      closing = closingFor(price, o);
      down = o.cash - closing;
      if (down < 0) return { error: 'Your cash does not cover the closing costs of ' + money.format(closing) + ', so nothing is left for a down payment.' };
      if (down >= price) return { error: 'Your cash covers the whole price and closing costs, so you would not need a mortgage.' };
    }
    return { price: price, down: down, closing: closing };
  }

  function showFields(mode) {
    el('dpPriceWrap').hidden = mode === 'cash';
    el('dpCashWrap').hidden = mode === 'price';
    el('dpPctWrap').hidden = mode === 'both';
  }

  function clearResults() {
    ['dpMain', 'dpPriceOut', 'dpDownOut', 'dpCashOut', 'dpLoanOut', 'dpPI', 'dpDownPctOut', 'dpClosingOut', 'dpLtv']
      .forEach(function (id) { setText(id, '–'); });
    setText('dpNote', '');
    el('dpOptions').innerHTML = '';
  }

  function update() {
    var mode = el('dpMode').value;
    showFields(mode);
    setText('dpMainLabel', LABELS[mode] || LABELS.cash);
    var o = {
      price: read('dpPrice'), cash: read('dpCash'), pct: read('dpPct'),
      cc: read('dpClosing', true), ccUnit: el('dpClosingUnit').value, include: el('dpIncludeClosing').checked,
      rate: read('dpRate'), years: read('dpTerm')
    };
    var msg = '';
    if (mode !== 'cash' && (isNaN(o.price) || o.price <= 0)) msg = 'Enter a home price greater than $0.';
    else if (mode !== 'price' && (isNaN(o.cash) || o.cash <= 0)) msg = 'Enter the cash you have available, greater than $0.';
    else if (mode !== 'both' && (isNaN(o.pct) || o.pct < 0 || o.pct >= 100)) msg = 'Enter a down payment from 0% to just under 100%.';
    else if (isNaN(o.cc) || o.cc < 0) msg = 'Closing costs cannot be negative.';
    else if (o.ccUnit === 'percent' && o.cc > 15) msg = 'Enter closing costs of 15% of the price or less.';
    else if (isNaN(o.rate) || o.rate < 0 || o.rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(o.years) || o.years < 1 || o.years > 50 || o.years % 1 !== 0) msg = 'Enter a loan term of 1 to 50 whole years.';
    var r = msg ? null : solve(mode, o);
    if (r && r.error) msg = r.error;
    var error = el('dpError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var loan = r.price - r.down, months = o.years * 12, downPct = r.down / r.price * 100;
    var cashNeeded = r.down + r.closing;
    setText('dpMain', mode === 'cash' ? money0.format(r.price) : mode === 'price' ? money0.format(cashNeeded) : downPct.toFixed(1) + '%');
    setText('dpPriceOut', money.format(r.price));
    setText('dpDownOut', money.format(r.down));
    setText('dpCashOut', money.format(cashNeeded));
    setText('dpLoanOut', money.format(loan));
    setText('dpPI', money.format(payment(loan, o.rate, months)));
    setText('dpDownPctOut', downPct.toFixed(1) + '%');
    setText('dpClosingOut', o.include ? money.format(r.closing) : 'Not included');
    setText('dpLtv', (loan / r.price * 100).toFixed(1) + '%');

    var note;
    if (downPct >= 20 - 1e-9) note = 'With 20% or more down, a conventional loan needs no private mortgage insurance (PMI).';
    else if (downPct >= 3.5 - 1e-9) note = 'Under 20% down, expect monthly mortgage insurance: PMI on a conventional loan, or MIP on an FHA loan. It is not included in the payment above.';
    else if (downPct >= 3 - 1e-9) note = 'A 3% down payment is the floor for some conventional programs (often for first-time buyers), with PMI. FHA loans need 3.5%.';
    else note = 'Under 3% down usually means a VA or USDA loan, which can allow 0% down if you qualify.';
    setText('dpNote', note);

    el('dpOptionsCaption').textContent = 'Each row uses the ' + money0.format(r.price) + ' price, your closing costs, rate and term.';
    el('dpOptions').innerHTML = OPTIONS.map(function (opt) {
      var down = r.price * opt.pct / 100, closing = closingFor(r.price, o), l = r.price - down;
      return '<tr><td>' + opt.pct + '%</td><td>' + money0.format(down) + '</td><td>' + money0.format(down + closing) + '</td><td>' +
        money0.format(l) + '</td><td>' + money.format(payment(l, o.rate, months)) + '</td><td>' + opt.note + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('dpForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
